  return rules.reduce((total, rule) => rule.apply(total, order), subtotal);
}

function withTwoNewRules(order) {
  const roundingRule = { name: "rounding", apply: (total) => Math.round(total) };
  const minimumChargeRule = {
    name: "minimum-charge",
    apply: (total) => (total < 5 ? 5 : total),
  };
  const rules = [...defaultRules, roundingRule, minimumChargeRule];
  return runPricingRules(order.subtotal, order, rules);
}

